-- Write the full Real Estate Virtual Assistant course.
-- Content remains draft and unpublished until practitioner review.

update public.training_courses
set estimated_minutes = 360,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    status = 'draft',
    published_at = null,
    updated_at = now()
where slug = 'real-estate-virtual-assistant';

update public.training_lessons l
set content = '[{"type":"heading","text":"What you should understand by the end"},{"type":"list","items":["The most common people involved in real estate operations and what each person is responsible for","Which activities a Virtual Assistant can usually support safely as administration","Why role boundaries change by market, brokerage, agency, property type, and local law","How to map a client''s actual workflow before touching CRM, listings, contracts, or customer communication"]},{"type":"heading","text":"Real estate is a team sport"},{"type":"paragraph","text":"A real estate business may look simple from the outside: someone lists a property, someone enquires, and eventually a deal closes. In practice, the work is spread across agents, brokers, property managers, transaction coordinators, leasing staff, photographers, conveyancers or attorneys, lenders, inspectors, contractors, cleaners, owners, tenants, buyers, sellers, and administrative staff. Your job as a VA is not to memorize every job title. It is to understand who owns which decisions, what information moves between them, and where your administrative support fits."},{"type":"heading","text":"Common roles you may support"},{"type":"list","items":["Sales agent or realtor: manages prospects, listings, negotiations, offers, and client relationships within local licensing rules.","Broker, principal, or agency owner: oversees the business, compliance, team performance, and higher-risk decisions.","Property manager: coordinates tenant communication, maintenance, rent-related administration, inspections, and owner updates according to local rules.","Transaction coordinator or conveyancing support: tracks documents, dates, signatures, conditions, and handoffs without giving legal advice.","Leasing or buyer support: manages enquiries, appointments, application administration, and follow-ups.","Marketing support: coordinates listing assets, portals, social posts, email campaigns, flyers, and database marketing.","Virtual Assistant: handles approved remote administrative workflows that keep these people organized and responsive."]},{"type":"heading","text":"Your scope should be defined by authority, not confidence"},{"type":"paragraph","text":"A confident VA can still create risk by doing something the client did not authorize. Real estate often involves regulated activity, financial commitments, contracts, disclosures, tenancy rights, privacy, fair-housing or anti-discrimination requirements, and deadlines with legal consequences. Never assume that because you understand a process you are allowed to make the decision inside it."},{"type":"callout","title":"The boundary rule","text":"If the task changes price, legal terms, contractual rights, tenancy obligations, disclosure language, deposit handling, eligibility, or a regulated representation, do not improvise. Follow the client''s documented workflow and escalate the decision to the responsible licensed or authorized person."},{"type":"heading","text":"Map the client''s workflow before doing the work"},{"type":"steps","items":["Identify the business type: sales, leasing, property management, buyer representation, commercial, short-term rental, or mixed.","List the main people involved and who can approve what.","Identify the source-of-truth systems: CRM, property-management software, shared drive, email, calendar, listing portal, transaction platform, or spreadsheet.","Find the written SOPs, templates, scripts, checklists, naming rules, and escalation contacts.","Ask which tasks you may complete independently and which require approval.","Confirm how urgent, sensitive, legal, financial, or customer complaints should be escalated.","Document the workflow so another person could understand it without relying on your memory."]},{"type":"scenario","title":"Who owns the decision?","text":"A buyer asks whether the seller would accept an offer below the listed price. You have access to the CRM and know the seller previously discussed a minimum figure with the agent. You should not answer on the seller''s behalf. Record the enquiry, preserve the buyer''s wording, flag the agent, and use the approved response process. The useful VA action is accurate routing and context, not negotiation."},{"type":"heading","text":"What good real-estate support looks like"},{"type":"list","items":["The CRM reflects what actually happened, not what you hope will happen.","Appointments, reminders, and access details are clear and in the correct time zone.","Property facts come from approved source material and are checked before publication.","Documents are named, stored, and tracked consistently.","Open tasks have owners and deadlines.","Customers receive timely administrative updates without unauthorized promises.","Exceptions are escalated early instead of hidden until they become emergencies."]},{"type":"heading","text":"Lesson check"},{"type":"list","items":["Can you name the decision owner for pricing, contracts, legal interpretation, and regulated advice?","Can you identify the systems that hold the source of truth?","Do you know which actions you may take without approval?","Would another person be able to continue your work from your notes and task history?"]}]'::jsonb,
    estimated_minutes = 30,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'real-estate-virtual-assistant'
  and l.slug = 'how-real-estate-businesses-and-teams-work';

update public.training_lessons l
set content = '[{"type":"heading","text":"Why the journey matters"},{"type":"paragraph","text":"Real-estate administration becomes much easier when you understand what happens before and after the task in front of you. A lead record is not just data entry. It may become a viewing, listing appointment, tenancy application, offer, transaction, settlement, maintenance request, or long-term client relationship. Your updates should help the next stage happen cleanly."},{"type":"heading","text":"A simplified sales journey"},{"type":"steps","items":["Lead or enquiry arrives from a portal, website, phone call, referral, event, database, advertisement, or social channel.","The team records the person, property, source, interest, timing, and next action.","A licensed or authorized team member handles qualification, advice, representation, pricing, and negotiation as required.","Appointments, inspections, listing presentations, or viewings are scheduled.","Property information and approved marketing assets are prepared and published.","Enquiries and follow-ups are documented.","Offers, negotiations, contracts, conditions, finance, inspection, legal, and settlement steps are tracked by the responsible people.","The file is closed, archived, handed over, or moved into long-term follow-up."]},{"type":"heading","text":"A simplified property-management journey"},{"type":"steps","items":["Owner or property is onboarded with approved agreements, contacts, access, and property information.","Marketing or leasing activity is coordinated if required.","Applications and supporting documents are collected and routed according to the client''s process.","Tenancy or occupancy information is entered into the source-of-truth system.","Routine communication, rent-related administration, maintenance requests, inspections, notices, and renewals are tracked according to local rules.","Exceptions, arrears, complaints, emergencies, legal notices, and high-risk matters are escalated.","When occupancy ends, the team follows the client''s approved move-out, inspection, deposit/bond, maintenance, and archive process."]},{"type":"heading","text":"Your job is continuity"},{"type":"paragraph","text":"A VA creates value when the next person does not need to reconstruct the story. Each stage should leave a reliable record: what happened, when it happened, who owns the next action, what the deadline is, and which document or communication supports the status."},{"type":"callout","title":"Do not convert administrative tracking into professional advice","text":"You may track that a finance condition is due, a contract is unsigned, an inspection report was received, or a tenancy document is missing. You should not interpret the legal effect of those facts unless that responsibility is clearly within your authorized and qualified role."},{"type":"heading","text":"Stage fields worth tracking"},{"type":"list","items":["Contact name and verified contact details","Property or project","Lead or transaction source","Current stage","Last meaningful activity","Next action","Next-action owner","Due date and time zone","Open decision or blocker","Relevant document, thread, or task link"]},{"type":"scenario","title":"The ''stuck'' transaction","text":"A file is marked ''under contract'' but there has been no activity for six days. Do not assume the deal is fine or change the stage. Review the task history, identify the last confirmed milestone, check for known due dates, and prepare a concise exception note for the responsible coordinator or agent."},{"type":"heading","text":"Common failure patterns"},{"type":"list","items":["Changing a stage because a customer sounded interested rather than because the required event actually happened.","Creating duplicate contacts instead of updating the existing record.","Using private notes as the only place where a key deadline is recorded.","Publishing a property fact from an old listing rather than the current approved source.","Letting a follow-up date pass without an owner.","Treating contract, tenancy, disclosure, or deposit questions as routine admin when they require authorized review."]},{"type":"heading","text":"Lesson check"},{"type":"paragraph","text":"Choose one real-estate workflow your future client might use. Draw the stages from first enquiry to final handoff. For each stage, write the trigger that moves the record forward, the person who owns the decision, and the evidence that proves the stage is correct."}]'::jsonb,
    estimated_minutes = 30,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'real-estate-virtual-assistant'
  and l.slug = 'the-real-estate-client-and-transaction-journey';

update public.training_lessons l
set content = '[{"type":"heading","text":"Lead intake is the first quality-control point"},{"type":"paragraph","text":"When an enquiry arrives, the first record often becomes the basis for future calls, emails, appointments, reporting, and attribution. If the first record is incomplete or duplicated, every later step becomes harder. Your goal is to capture reliable information without pretending to make qualification decisions that belong to sales or licensed staff."},{"type":"heading","text":"Capture facts, not assumptions"},{"type":"list","items":["Name exactly as provided or confirmed","Preferred contact details","Property address or area of interest when relevant","Enquiry source","Reason for enquiry","Timing or timeframe if the person stated one","Appointment preference if provided","Consent or communication preferences where the workflow requires them","What the person actually said","The next approved action"]},{"type":"heading","text":"Qualification support is not qualification authority"},{"type":"paragraph","text":"Some clients give VAs a script or checklist to collect information such as desired location, budget range, move date, property type, or whether someone is selling before buying. You may collect and organize those answers. Unless your client has explicitly authorized you and local rules permit it, do not decide that someone is ''good'', ''bad'', ''approved'', ''unqualified'', or unsuitable based on your own judgment."},{"type":"callout","title":"Sensitive criteria","text":"Do not create your own screening rules based on protected characteristics or personal assumptions. Housing-related anti-discrimination rules differ by jurisdiction, but the safe operating principle is universal: follow the client''s lawful approved criteria and escalate anything unclear."},{"type":"heading","text":"A clean intake workflow"},{"type":"steps","items":["Search the CRM before creating a new contact.","Check likely duplicates using email, phone, full name, property, and existing household/company links.","Create or update the record using the client''s field rules.","Record the enquiry source accurately.","Paste or summarize the request without changing its meaning.","Apply only approved tags, stages, owners, and next actions.","Create the follow-up task or appointment if the workflow allows it.","Link the original email, form, call note, or message where possible.","Flag missing or contradictory information instead of guessing."]},{"type":"heading","text":"CRM hygiene standards"},{"type":"list","items":["One person should not have three records just because they used different channels.","Phone numbers and addresses should follow the client''s standard format.","Stages should represent real events, not optimism.","Tags should have defined meanings.","Notes should be factual and professional.","Tasks should have owners and due dates.","Old records should not be deleted merely because they look inactive unless policy allows it."]},{"type":"scenario","title":"Duplicate lead with different details","text":"A new website enquiry uses the same phone number as an existing CRM contact but a different email address and a slightly different surname spelling. Do not create a fresh lead immediately. Compare the records, preserve the new source and enquiry, and follow the client''s duplicate-resolution rule. If identity is unclear, flag it rather than merging two people incorrectly."},{"type":"heading","text":"Bad notes create future risk"},{"type":"paragraph","text":"Avoid comments such as ''time waster'', ''difficult'', ''seems rich'', ''probably won''t qualify'', or other subjective judgments unless there is a defined business reason and an approved field for factual qualification data. Notes may be seen by colleagues, customers, auditors, regulators, or future staff. Write what happened, not your personal label."},{"type":"heading","text":"Practice checklist"},{"type":"list","items":["Search before creating.","Use source evidence.","Record the customer''s words accurately.","Use approved fields and stages.","Create the next action.","Escalate uncertain qualification decisions."]}]'::jsonb,
    estimated_minutes = 30,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'real-estate-virtual-assistant'
  and l.slug = 'lead-intake-qualification-support-and-crm-hygiene';

update public.training_lessons l
set content = '[{"type":"heading","text":"Follow-up is a system, not memory"},{"type":"paragraph","text":"Real-estate businesses often lose opportunities because leads are entered but no next action is created. A VA can add major value by making follow-up visible and consistent, provided the cadence, channels, scripts, and authority are defined by the client."},{"type":"heading","text":"Every active record needs a reason to be active"},{"type":"list","items":["A scheduled call, email, message, or appointment","A document or decision you are waiting for","A specific date when the client wants the person re-contacted","A milestone that will trigger the next action","A defined long-term nurture sequence","A clear status showing that no further action is currently required"]},{"type":"heading","text":"Designing a follow-up queue"},{"type":"steps","items":["Start with overdue tasks and missed commitments.","Separate urgent customer-impacting follow-ups from routine nurture.","Check whether the last action actually happened before sending another message.","Review recent replies so you do not send a generic follow-up after the situation changed.","Use the approved channel and message template.","Record the result and create the next action immediately.","Escalate replies involving offers, negotiation, legal questions, complaints, sensitive housing issues, or other restricted decisions."]},{"type":"callout","title":"Do not automate annoyance","text":"A sequence is not automatically good because software can send it. Respect opt-outs, consent rules, channel policies, client instructions, and context. Stop or change automation when the person''s reply makes the scheduled message inappropriate."},{"type":"heading","text":"Database maintenance without destroying history"},{"type":"list","items":["Merge only confirmed duplicates under the client''s process.","Standardize obvious formatting issues without rewriting customer-provided facts.","Archive or suppress records only according to policy.","Preserve lead source and activity history when consolidating records.","Do not erase lost opportunities simply to improve conversion reports.","Keep unsubscribe and communication-preference records intact."]},{"type":"scenario","title":"The follow-up list says 42 overdue","text":"Do not blast all 42 contacts with the same message. Sort by stage, last activity, owner, age, and reason for follow-up. Check replies and active transactions first. Some may need a task update, some may be stale, some may already be working with the team, and some may require a different message entirely."},{"type":"heading","text":"Useful follow-up reporting"},{"type":"list","items":["Overdue tasks by owner","Leads with no future action","Records waiting on client decisions","Appointments not confirmed","Replies requiring agent or property-manager response","Long-term nurture records reaching their review date","Duplicate or incomplete records that need cleanup"]},{"type":"heading","text":"End-of-day discipline"},{"type":"paragraph","text":"Before you finish, make sure every meaningful conversation has a note, every active matter has a next action, and every exception has an owner. A clean database is less about perfect formatting and more about making the next correct action obvious."},{"type":"scenario","title":"Follow-up handoff","text":"An owner replies that they want to speak with the agent next month rather than this week. Update the record with the exact timing, create a future task in the correct time zone, note the reason, and stop any conflicting sequence if the client''s workflow requires it."}]'::jsonb,
    estimated_minutes = 30,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'real-estate-virtual-assistant'
  and l.slug = 'follow-up-workflows-and-database-management';

update public.training_lessons l
set content = '[{"type":"heading","text":"Listing coordination is dependency management"},{"type":"paragraph","text":"A property should not go live simply because someone says ''publish it''. Listing work often depends on verified property details, approved copy, photography, floor plans, disclosures, agency details, pricing instructions, portal access, open-home or viewing times, and final approval. Your role is to make those dependencies visible."},{"type":"heading","text":"Build a source-of-truth checklist"},{"type":"list","items":["Correct property address and unit details","Approved property type and key features","Approved price or pricing language","Approved listing description","Correct agent or property-manager contact information","Approved photos and image order","Floor plans or supporting media where applicable","Inspection, viewing, or open-home information","Required disclosures, disclaimers, or local fields supplied by the authorized team","Portal or website destinations","Approval status and approver"]},{"type":"heading","text":"Asset workflow"},{"type":"steps","items":["Create one task or checklist for the listing.","Link the source folder rather than scattering attachments across messages.","Name assets consistently.","Confirm which images and versions are approved.","Check orientation, cropping, obvious duplicates, missing rooms, and unreadable text overlays.","Do not edit property features, room counts, measurements, or material claims based on visual guesswork.","Record final approval before publishing.","After launch, check the live result instead of assuming the upload worked."]},{"type":"callout","title":"Photos are not factual proof","text":"A photo may suggest that a room is large, renovated, accessible, furnished, or recently improved, but you should not convert visual impressions into factual property claims without approved source information."},{"type":"heading","text":"Copy quality assurance"},{"type":"list","items":["Address and suburb/area are correct.","Names and contact details are correct.","Features match approved source data.","Dates and viewing times use the correct local time zone.","Links work.","No placeholder text remains.","No prohibited, discriminatory, or unapproved language has been introduced.","The live page matches the approved version."]},{"type":"scenario","title":"The brochure and CRM disagree","text":"The brochure says three bedrooms, while the CRM says four. Do not choose whichever seems more likely from the photos. Stop the publication of that factual field, identify the approved source or responsible person, and record the discrepancy so it can be corrected at the source."},{"type":"heading","text":"Launch handoff"},{"type":"steps","items":["Confirm the property is live in each approved destination.","Capture or link the live URLs.","Record the launch time.","Check enquiry routing.","Confirm scheduled inspections or viewings.","Notify the responsible team using the approved update format.","Create any post-launch monitoring or follow-up tasks."]},{"type":"heading","text":"What not to do"},{"type":"list","items":["Copy an old listing''s description without checking current facts.","Publish before price, compliance fields, or approval are confirmed.","Use unlicensed images or assets whose permission is unclear.","Change legal or disclosure wording to make it sound better.","Assume that because a portal accepted the listing, the information is correct."]}]'::jsonb,
    estimated_minutes = 30,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'real-estate-virtual-assistant'
  and l.slug = 'listing-coordination-and-asset-checklists';

update public.training_lessons l
set content = '[{"type":"heading","text":"Accuracy beats speed when facts matter"},{"type":"paragraph","text":"Real-estate teams often reuse property information across CRM records, websites, portals, brochures, email campaigns, transaction folders, inspection schedules, and reports. A single incorrect field can propagate everywhere. Good administration checks important facts against the approved source before copying them forward."},{"type":"heading","text":"Separate fact types"},{"type":"list","items":["Identity facts: address, lot/unit, owner/client, contact, property ID.","Physical facts: bedrooms, bathrooms, parking, area, features, inclusions.","Commercial facts: approved price, rent, fees, availability, campaign dates.","Process facts: stage, appointment date, condition deadline, inspection status, document status.","Legal/compliance information: disclosures, tenancy notices, contract fields, statutory or regulated information supplied by authorized professionals."]},{"type":"heading","text":"Use a source hierarchy"},{"type":"steps","items":["Follow the client''s defined source-of-truth system first.","If two internal sources conflict, stop and flag the conflict.","Prefer current approved documents over old marketing material.","Do not treat search results, old portal copies, AI answers, or third-party aggregators as authoritative for sensitive property facts.","When a fact changes, update the source record first when the workflow allows, then update dependent outputs."]},{"type":"callout","title":"A document can be current and still require review","text":"Having the latest file does not mean you are qualified to interpret its legal meaning. You may track that a document exists, is signed, is missing, or contains a date, while leaving interpretation to the authorized professional."},{"type":"heading","text":"Document-control habits"},{"type":"list","items":["Use consistent naming with property, document type, and useful date/version information.","Avoid files named FINAL, FINAL2, or USE-THIS unless that is the client''s standard.","Keep executed/signed versions distinguishable from drafts.","Use access permissions appropriate to the sensitivity of the file.","Do not move or delete files merely to make folders look tidy if other systems link to them.","Record when a required document is missing, expired, or awaiting signature."]},{"type":"scenario","title":"Signed or unsigned?","text":"A folder contains two copies of the same agreement. One filename says SIGNED, but the file itself is missing one signature. Do not rename the file to make it appear complete. Record what is visibly present, flag the discrepancy, and ask the responsible person which version is authoritative."},{"type":"heading","text":"Pre-publication and pre-handoff QA"},{"type":"list","items":["Correct property and client","Correct dates and time zones","Correct version","Required signatures or approvals visibly present if your checklist asks you to confirm them","No missing attachments","No accidental personal information in public-facing material","No broken links","No unsupported property claims","No unresolved conflicts between systems"]},{"type":"heading","text":"The exception log"},{"type":"paragraph","text":"For high-volume work, maintain a simple exception log: property, issue, source checked, owner, date raised, deadline, current status. This is far more useful than repeatedly rediscovering the same discrepancy in chat."}]'::jsonb,
    estimated_minutes = 30,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'real-estate-virtual-assistant'
  and l.slug = 'property-information-documents-and-quality-checks';

update public.training_lessons l
set content = '[{"type":"heading","text":"Scheduling is part of the customer experience"},{"type":"paragraph","text":"A viewing or inspection can involve the prospect, agent, tenant, owner, building access, keys, travel time, local notice requirements, and other appointments. The VA''s job is to coordinate within the client''s rules and make the logistics clear."},{"type":"heading","text":"Before offering a time"},{"type":"list","items":["Confirm which calendar controls availability.","Check the responsible person''s working hours and travel buffers.","Check whether the property has access restrictions.","Follow any notice or consent process required by the client and local rules.","Know whether the appointment is private, group, virtual, or open-house/open-home style.","Confirm the correct local time zone.","Check whether another appointment or hold already exists."]},{"type":"heading","text":"Booking workflow"},{"type":"steps","items":["Identify the property and appointment type.","Confirm the attendee''s full name and reliable contact details.","Offer only approved time options.","Record the agreed time in the correct calendar.","Include property, purpose, responsible staff member, location/access notes, and relevant links.","Send the approved confirmation.","Create reminders according to the client''s process.","Update CRM or property software so the appointment is visible outside the calendar.","Record cancellation, reschedule, no-show, or completion status afterward."]},{"type":"callout","title":"Never guess access","text":"Do not send lockbox, alarm, entry-code, tenant-access, or key instructions unless the client has an approved secure workflow for sharing them with that recipient."},{"type":"heading","text":"Handling changes"},{"type":"list","items":["If the customer requests a new time, re-check availability rather than moving the event blindly.","If the responsible agent is delayed, tell affected people as soon as you have verified information.","If access is uncertain, escalate before sending a customer to the property.","If a current occupant, tenant, or owner raises a concern, pause and follow the client''s access/notice procedure."]},{"type":"scenario","title":"Two appointments, one travel problem","text":"An agent has a viewing at 10:00 and another property appointment at 10:30 across town. The calendar technically shows both as available because the first meeting is only 20 minutes. Do not rely on meeting duration alone. Apply the client''s travel-buffer rules, flag the conflict, and offer approved alternatives."},{"type":"heading","text":"Confirmation quality"},{"type":"list","items":["Correct date","Correct local time and time zone if relevant","Correct property address","Correct contact person","Correct meeting type","Correct joining or arrival instructions","A clear reschedule/cancel method","No sensitive access information sent outside approved channels"]},{"type":"heading","text":"After the appointment"},{"type":"paragraph","text":"Update the outcome using approved stages and facts. If feedback belongs to the agent, do not invent it. Create the next follow-up task based on the client''s process so the viewing does not disappear from the pipeline."}]'::jsonb,
    estimated_minutes = 30,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'real-estate-virtual-assistant'
  and l.slug = 'inspections-viewings-and-appointment-coordination';

update public.training_lessons l
set content = '[{"type":"heading","text":"Different audiences need different information"},{"type":"paragraph","text":"A buyer waiting for a viewing time, a seller waiting for campaign activity, a tenant reporting a broken appliance, and a contractor waiting for access are all ''contacts'', but their expectations and the risks of saying the wrong thing are different. Use the client''s approved communication process and give only information you are authorized to give."},{"type":"heading","text":"A useful update has four parts"},{"type":"steps","items":["State the current confirmed status.","State what action has been taken.","State what is still waiting or blocked.","State the next step, owner, or expected update time if known."]},{"type":"heading","text":"Buyer and prospect updates"},{"type":"list","items":["Appointment confirmations and changes","Approved property information","Document or information requests","Follow-up scheduling","Routing offer, finance, negotiation, or representation questions to the responsible person"]},{"type":"heading","text":"Seller and owner updates"},{"type":"list","items":["Administrative campaign milestones","Scheduled photography, listing launch, or inspection information","Confirmed enquiry or appointment counts if the client reports them","Maintenance status","Outstanding approvals or documents","Never inventing market advice, valuation, legal interpretation, or promises about outcomes"]},{"type":"heading","text":"Tenant or occupant updates"},{"type":"list","items":["Receipt of maintenance requests","Approved appointment windows","Routine access coordination","Status of authorized repairs","Routing urgent safety, habitability, legal, payment, or dispute issues according to the client''s escalation process"]},{"type":"heading","text":"Vendor and contractor updates"},{"type":"list","items":["Job scope as approved by the client","Property and access details through approved channels","Appointment timing","Required evidence such as quote, invoice, completion photo, or report","Approval status","No unauthorized changes to price, scope, or payment commitment"]},{"type":"callout","title":"Do not smooth over uncertainty","text":"If you are still waiting for approval, say that. ''The property manager is reviewing the quote and I will update you once approval is confirmed'' is safer than implying the job is approved."},{"type":"scenario","title":"The angry tenant and the unapproved contractor","text":"A tenant says a leak is getting worse. A contractor is available today but has quoted more than the client''s approval limit. Your job is to follow the emergency/escalation procedure, document the new information, and get the correct authorization. Do not approve extra cost merely because the situation feels urgent unless the client''s emergency authority explicitly allows it."},{"type":"heading","text":"Communication quality check"},{"type":"list","items":["Is every factual statement confirmed?","Did I accidentally promise timing, approval, price, legal outcome, or negotiation result?","Did I identify the next owner?","Did I preserve the customer''s original concern accurately?","Did I use the right channel for sensitive information?","Did I record the communication in the source system?"]}]'::jsonb,
    estimated_minutes = 30,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'real-estate-virtual-assistant'
  and l.slug = 'buyer-seller-tenant-and-vendor-updates';

update public.training_lessons l
set content = '[{"type":"heading","text":"High stakes require disciplined boundaries"},{"type":"paragraph","text":"Once a property transaction reaches offer, contract, application, or formal agreement stages, administrative mistakes can have serious consequences. A VA can be extremely useful by tracking dates, documents, signatures, tasks, and communications, but should not interpret legal effect, negotiate terms without authority, or give professional advice."},{"type":"heading","text":"What administration may include"},{"type":"list","items":["Creating a transaction checklist from the client''s approved template","Recording confirmed milestone dates","Tracking whether required documents have been received","Sending approved reminders","Coordinating appointments with authorized providers","Maintaining the transaction folder","Updating task status","Preparing a factual outstanding-items summary","Escalating approaching deadlines"]},{"type":"heading","text":"What usually needs authorized or licensed ownership"},{"type":"list","items":["Explaining what a contract clause means","Advising whether someone should sign","Negotiating price or legal terms unless that is explicitly within the person''s authorized role","Giving legal, tax, finance, conveyancing, inspection, or regulatory advice","Changing contractual dates or obligations without documented approval","Handling deposits, trust money, escrow, or client funds outside the client''s regulated process"]},{"type":"callout","title":"Track the deadline; do not interpret the consequence","text":"You can say, ''The finance-condition date recorded in the transaction checklist is Friday and the task is still open.'' You should not tell the client what happens legally if the condition is missed unless you are qualified and authorized to do so."},{"type":"heading","text":"Transaction checklist discipline"},{"type":"steps","items":["Create the file from the approved template.","Link the source contract or transaction record.","Record dates exactly as supplied by the responsible person or approved source.","Assign tasks to the correct owners.","Use reminders early enough to allow action.","Track document status: requested, received, reviewed by responsible person, signed/executed, or outstanding.","Escalate discrepancies rather than correcting legal fields yourself.","Close or archive only after the client''s completion checklist is satisfied."]},{"type":"scenario","title":"Two different settlement dates","text":"The CRM shows one date while a newer document appears to show another. Do not silently update the CRM from your interpretation of the document. Flag the conflict to the transaction owner, link both sources, and update the system only after the responsible person confirms the correct date."},{"type":"heading","text":"Outstanding-items report"},{"type":"list","items":["Item","Current status","Responsible owner","Source or document link","Due date","Last follow-up","Risk or dependency","Next action"]},{"type":"heading","text":"A professional handoff"},{"type":"paragraph","text":"Your handoff should allow the authorized agent, coordinator, lawyer, conveyancer, broker, or manager to make the decision quickly because the facts and supporting materials are organized. That is the VA''s leverage: reducing administrative friction without pretending to be the professional who owns the legal or commercial judgment."}]'::jsonb,
    estimated_minutes = 30,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'real-estate-virtual-assistant'
  and l.slug = 'contract-to-close-administration-boundaries';

update public.training_lessons l
set content = '[{"type":"heading","text":"Maintenance requests need structure"},{"type":"paragraph","text":"Property-management support often involves maintenance, but a VA should not treat every request the same. A dripping tap, no power, water leak, broken lock, appliance failure, suspected gas issue, and cosmetic repair may have very different urgency and escalation paths. Follow the client''s emergency definitions and local obligations rather than inventing your own."},{"type":"heading","text":"Capture enough information to act"},{"type":"list","items":["Property and unit","Reporter name and contact","What happened, in the reporter''s own words","When it started","Whether there is immediate safety, security, water, electrical, access, or property-damage concern","Photos or videos if requested and safe","Access availability","Previous related job if known","Any temporary step already taken","Preferred or approved vendor if the workflow specifies one"]},{"type":"heading","text":"Triage using the client''s rules"},{"type":"steps","items":["Check the approved emergency/urgent/routine criteria.","If the report matches an emergency criterion, follow the emergency escalation immediately.","If severity is unclear, escalate rather than down-classifying it yourself.","Create the maintenance job in the source system.","Attach supporting evidence.","Contact the approved vendor or responsible manager according to authority limits.","Track quote, approval, scheduling, access, completion, invoice, and follow-up.","Keep the resident/owner updated with confirmed information."]},{"type":"callout","title":"Safety outranks workflow neatness","text":"If a report suggests immediate danger, serious water damage, security risk, fire, gas, electrical hazard, or another emergency defined by the client, follow the emergency process first. Do not wait for a perfect ticket before escalating."},{"type":"heading","text":"Vendor coordination boundaries"},{"type":"list","items":["Send the approved job scope, not your own technical diagnosis.","Do not authorize spending above your delegated limit.","Do not expand the repair scope without approval.","Keep quote and invoice records linked to the job.","Record appointment details and access instructions securely.","Request completion evidence required by the client.","Escalate disputes, repeat failures, or safety concerns."]},{"type":"scenario","title":"Quote above authority","text":"A plumber confirms the leak can be repaired today for an amount above your approval limit. The resident is waiting. Document the quote, flag urgency, notify the authorized manager, and use the emergency process if applicable. Do not approve the extra amount unless your documented authority allows it."},{"type":"heading","text":"Closing a maintenance job"},{"type":"steps","items":["Confirm the vendor reports the job complete.","Collect required invoice, notes, photos, or report.","Confirm the resident or property contact has been updated if required.","Record any follow-up or warranty item.","Route invoice approval according to process.","Close the task only when the client''s completion criteria are met."]},{"type":"heading","text":"Useful maintenance reporting"},{"type":"list","items":["Open jobs by age and priority","Jobs waiting on owner/manager approval","Jobs waiting on access","Quotes awaiting decision","Repeat issues at the same property","Overdue vendor commitments","Completed jobs awaiting invoice or final evidence"]}]'::jsonb,
    estimated_minutes = 30,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'real-estate-virtual-assistant'
  and l.slug = 'maintenance-and-property-management-support';

update public.training_lessons l
set content = '[{"type":"heading","text":"Reporting should help someone decide what to do"},{"type":"paragraph","text":"A long list of everything you touched is not automatically a useful report. Real-estate teams need visibility into outcomes, deadlines, customer issues, blocked transactions, overdue follow-ups, listing readiness, maintenance exceptions, and decisions that require attention."},{"type":"heading","text":"Separate activity from outcome"},{"type":"list","items":["Activity: 35 follow-up emails sent. Outcome: 4 replies, 2 appointments booked, 1 request for no further contact, 1 agent decision needed.","Activity: 12 CRM records updated. Outcome: 8 now have valid next actions, 3 duplicates need review, 1 record is missing ownership.","Activity: 5 maintenance jobs checked. Outcome: 2 complete, 1 awaiting invoice, 1 awaiting approval, 1 urgent escalation."]},{"type":"heading","text":"A practical daily handoff structure"},{"type":"steps","items":["Completed: important outcomes finished today.","Waiting: items blocked by another person, document, customer, or vendor.","Decisions needed: questions only the responsible person can answer.","Deadlines: anything due soon or at risk.","Customer issues: complaints, urgent messages, or sensitive replies.","Tomorrow: first actions already queued."]},{"type":"callout","title":"Lead with exceptions","text":"If everything routine is on track, summarize it briefly. Put the unusual, overdue, high-risk, or decision-dependent items where the reader sees them first."},{"type":"heading","text":"Common operational reports"},{"type":"list","items":["Lead follow-up and appointment report","Listing readiness report","Transaction outstanding-items report","Maintenance exception report","Property/tenant communication queue","Vendor quote/approval report","Database hygiene report","Daily or weekly owner/manager action list"]},{"type":"heading","text":"Reporting integrity"},{"type":"list","items":["Use consistent date ranges.","Define what each metric means.","Do not count duplicate records as separate opportunities.","Do not move stages merely to improve reported conversion.","Separate confirmed data from estimates.","If the source is incomplete, state the limitation.","Link the underlying system or record where practical."]},{"type":"scenario","title":"A report says everything is fine","text":"Your dashboard shows no overdue tasks, but you discover that several leads have no next task at all. The dashboard is technically clean but operationally misleading. Report the gap and fix the process that allows active records to exist without a future action."},{"type":"heading","text":"Handoff example"},{"type":"paragraph","text":"Decision needed: 18 King St maintenance quote is above the normal approval limit. Vendor can attend tomorrow if approved by 3 PM local time. Quote is linked in the maintenance task. Resident has been told approval is pending. Owner: Property Manager. Next follow-up: 2 PM."},{"type":"heading","text":"Before ending your shift"},{"type":"list","items":["No urgent customer message is sitting unassigned.","Every active task has an owner.","Every meaningful deadline is visible.","Every exception has been escalated.","Tomorrow''s first actions are clear.","Your handoff contains links, not just descriptions."]}]'::jsonb,
    estimated_minutes = 30,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'real-estate-virtual-assistant'
  and l.slug = 'real-estate-reporting-and-daily-handoffs';

update public.training_lessons l
set content = '[{"type":"heading","text":"Final practice: run a realistic real-estate admin day"},{"type":"paragraph","text":"This simulation brings the course together. Treat every business, person, property, and document as fictional. Your goal is not to show that you can move quickly. Your goal is to show that you can protect accuracy, boundaries, customer experience, and continuity while several things happen at once."},{"type":"heading","text":"Scenario background"},{"type":"paragraph","text":"You support a fictional real-estate team that handles residential sales and a small property-management portfolio. The team uses a CRM, shared drive, task board, calendar, and maintenance tracker. Your supervisor has given you approved templates for routine communication and an escalation list for urgent, legal, financial, safety, and negotiation matters."},{"type":"heading","text":"Your incoming work"},{"type":"list","items":["A website lead asks to view a listed property this week and mentions they may need to sell their current home first.","A seller''s listing folder contains approved photos, but the CRM and brochure disagree on the bedroom count.","A buyer asks by email whether the seller would accept an offer below the advertised price.","An agent''s calendar shows two appointments with unrealistic travel time between them.","A tenant reports water spreading from under a kitchen sink and sends a photo.","A contractor is available today but the quote is above your delegated approval amount.","A transaction checklist shows a milestone due tomorrow but the supporting document is not marked received.","Three active CRM leads have no future follow-up task.","Your supervisor needs a concise end-of-day handoff."]},{"type":"heading","text":"Part 1: Prioritize"},{"type":"steps","items":["Put the nine items in the order you would investigate them.","For each item, write the consequence of delay.","Identify which items you can act on independently.","Identify which items require an authorized decision.","Identify any safety, legal, contractual, negotiation, financial, or privacy escalation."]},{"type":"heading","text":"Part 2: Produce the admin work"},{"type":"list","items":["Create the CRM intake note and next action for the website lead.","Write the discrepancy note for the bedroom-count conflict and identify the source you would seek.","Draft the safe response to the buyer''s price question without negotiating.","Propose a calendar fix for the travel conflict.","Create the maintenance-ticket summary from the tenant report.","Create the contractor-quote escalation note.","Create the transaction outstanding-item note.","Create follow-up tasks for the three CRM leads using reasonable fictional dates.","Prepare an end-of-day handoff covering outcomes, waiting items, decisions, deadlines, and tomorrow''s first actions."]},{"type":"callout","title":"Assessment standard","text":"You are assessed on accuracy, prioritization, documentation, boundaries, escalation, clarity, and continuity. You are not rewarded for making unauthorized decisions just to make the workflow look complete."},{"type":"heading","text":"Part 3: Self-review before submission"},{"type":"list","items":["Did you separate confirmed facts from assumptions?","Did you avoid negotiation, legal advice, contract interpretation, or unauthorized spending approval?","Did you prioritize the possible water-damage issue appropriately?","Did you preserve the customer''s original meaning in notes?","Did every active item receive a next owner or next action?","Did you use specific dates/times rather than vague phrases where timing matters?","Could another person continue from your handoff without asking you to reconstruct the day?"]},{"type":"heading","text":"What excellent work looks like"},{"type":"paragraph","text":"Excellent work is calm, specific, evidence-based, and bounded. You do not hide problems, but you also do not inflate every issue into an emergency. You move routine administration forward, stop at real decision boundaries, and make the next responsible action obvious."},{"type":"scenario","title":"Optional stretch scenario","text":"At the end of the day, the seller emails a corrected property fact directly to you while the listing is already live. Explain how you would verify authority, update the source of truth, identify dependent channels that may need correction, preserve the old record where appropriate, and report the change."}]'::jsonb,
    estimated_minutes = 30,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'real-estate-virtual-assistant'
  and l.slug = 'composite-real-estate-va-work-simulation';

update public.training_assessments
set instructions = 'Complete the full composite real-estate administration simulation from the final lesson and submit: (1) a prioritized work queue with reasons, (2) CRM intake and follow-up notes, (3) a property-data discrepancy escalation, (4) a safe buyer response that does not negotiate, (5) a corrected scheduling plan, (6) a maintenance ticket and above-authority quote escalation, (7) a transaction outstanding-item note, and (8) an end-of-day handoff. The reviewer should assess factual accuracy, prioritization, documentation quality, professional communication, escalation judgment, privacy, and whether the learner stayed within administrative boundaries. The learner must not provide legal advice, contract interpretation, regulated representation, unauthorized negotiation, or spending approval.',
    assessment_type = 'practical',
    pass_score = null,
    is_published = false,
    updated_at = now()
where course_id = (select id from public.training_courses where slug='real-estate-virtual-assistant');

